-- ds_check_history — GENERATED by tools/build_production.py from tools/dashboard_datasets.py.
-- Paste into the dashboard's Data tab as a dataset named ds_check_history.
-- One row per scheduled run and active check. Tables: Failed rows per table over time.

SELECT r.run_id, r.run_ts, r.run_day, k.rule_id, k.target_table, g.cde_id, e.cde_name,
       k.severity, e.business_domain, k.status AS verdict,
       k.rows_scanned, k.violation_count, k.violation_pct
FROM   sdpt_data_trnf.udp_brnz.dq_results_check_run k
JOIN   sdpt_data_trnf.udp_brnz.dq_results_v_scheduled_run r ON r.run_id = k.run_id
JOIN   sdpt_data_trnf.udp_brnz.dq_config_v_rule_registry_current g ON g.rule_id = k.rule_id AND g.status = 'active'
LEFT JOIN sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current e ON e.cde_id = g.cde_id
WHERE  k.status IN ('pass', 'breach')
